"""Correcao pontual: adiciona a imagem que faltou na Questao 10 do ENADE 2023.

Script de uso unico, seguro de rodar quantas vezes quiser: so atualiza a
questao se ela existir e ainda nao tiver imagem.
"""

from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

from app.core.config import DATABASE_URL
from app.database.base import Base
from app.models.questao import Questao

IMAGEM_QUESTAO_10_2023 = "data:image/jpeg;base64,"


def executar():
    engine = create_engine(DATABASE_URL)
    Base.metadata.create_all(engine)
    Session = sessionmaker(bind=engine)
    session = Session()

    questao = session.query(Questao).filter_by(ano=2023, numero=10).first()
    if questao is None:
        print("Questao 2023/10 nao encontrada no banco. Rode make seed-2023 primeiro.")
        session.close()
        return

    if questao.imagem:
        print("Questao 2023/10 ja tem imagem. Nada a fazer.")
        session.close()
        return

    questao.imagem = IMAGEM_QUESTAO_10_2023
    session.commit()
    print("Imagem adicionada a questao 2023/10 com sucesso.")
    session.close()


if __name__ == "__main__":
    executar()
